header('Content-Type: application/json; charset=utf-8');

$origin = $_SERVER['HTTP_ORIGIN'] ?? '';
$allowedOrigin = $origin ?: (($_SERVER['HTTPS'] ?? '') !== 'off' ? ('https://' . ($_SERVER['HTTP_HOST'] ?? '')) : ('http://' . ($_SERVER['HTTP_HOST'] ?? '')));
header('Access-Control-Allow-Origin: ' . $allowedOrigin);
header('Vary: Origin'); header('Access-Control-Allow-Credentials: true');
header('Access-Control-Allow-Methods: GET, POST, OPTIONS'); header('Access-Control-Allow-Headers: Content-Type');
if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') { http_response_code(204); exit; }
