function out($data,$code=200){http_response_code($code);echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;}
function body(){ $d=json_decode(file_get_contents('php://input'),true); return is_array($d)?$d:[]; }
function cfg(){ $p=__DIR__.'/config.php'; if(!file_exists($p)) out(['status'=>'error','message'=>'أنشئ public/config.php من config.example.php أولاً.'],500); $c=require $p; foreach(['host','dbname','user','pass'] as $k) if(!array_key_exists($k,$c)) out(['status'=>'error','message'=>'إعداد قاعدة البيانات ناقص.'],500); return $c; }
function db(){ static $pdo=null; if($pdo)return $pdo; $c=cfg(); try{$pdo=new PDO("mysql:host={$c['host']};dbname={$c['dbname']};charset=utf8mb4",$c['user'],$c['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){out(['status'=>'error','message'=>'تعذر الاتصال بقاعدة البيانات.'],500);} return $pdo; }
function user(){return $_SESSION['user']??null;}
function requireUser($roles=[]){$u=user();if(!$u)out(['status'=>'error','message'=>'يجب تسجيل الدخول أولاً.'],401);if($roles&&!in_array($u['role'],$roles,true))out(['status'=>'error','message'=>'ليس لديك صلاحية لتنفيذ هذا الإجراء.'],403);if($u['role']==='merchant'&&($u['status']??'active')==='suspended')out(['status'=>'error','message'=>'حساب البائع موقوف.'],403);return $u;}
function publicUser($u){return ['id'=>$u['id'],'name'=>$u['name'],'phone'=>$u['phone']??null,'companyName'=>$u['company_name']??null,'role'=>$u['role'],'status'=>$u['status']??'active','isLoggedIn'=>true];}
