 "CREATE TABLE IF NOT EXISTS orders (id VARCHAR(64) PRIMARY KEY,store_id VARCHAR(64) NOT NULL,customer_user_id VARCHAR(64),status VARCHAR(60) NOT NULL,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,data LONGTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(store_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS coupons (id VARCHAR(64) PRIMARY KEY,store_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,data LONGTEXT NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_store_code(store_id,code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS subscriptions (id VARCHAR(64) PRIMARY KEY,store_id VARCHAR(64) NOT NULL,status VARCHAR(60) NOT NULL,data LONGTEXT NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_sub_store(store_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
