function decodeStore($row){$s=json_decode($row['data']??'{}',true);if(!is_array($s))$s=[];return hydrateStoreTenant($s,$row['id']??'');}
function getStoreRow($id){$q=db()->prepare('SELECT * FROM stores WHERE id=? LIMIT 1');$q->execute([$id]);return $q->fetch();}
function owned($id,$uid){$q=db()->prepare('SELECT id FROM stores WHERE id=? AND merchant_user_id=? LIMIT 1');$q->execute([$id,$uid]);return(bool)$q->fetch();}
function tenantConfig(){ $c=cfg(); return ['enabled'=>(bool)($c['tenant_databases_enabled']??false),'host'=>$c['tenant_db_host']??$c['host'],'user'=>$c['tenant_db_user']??$c['user'],'pass'=>$c['tenant_db_pass']??$c['pass'],'prefix'=>$c['tenant_db_prefix']??'youmi_tenant_']; }
function tenantMeta($storeId){$q=db()->prepare('SELECT * FROM tenant_databases WHERE store_id=? LIMIT 1');$q->execute([$storeId]);return $q->fetch()?:null;}
function tenantDb($storeId){static $pool=[];if(isset($pool[$storeId]))return $pool[$storeId];$m=tenantMeta($storeId);$c=tenantConfig();if(!$m||!$c['enabled']||empty($m['db_name']))return null;try{$pool[$storeId]=new PDO("mysql:host={$m['db_host']};dbname={$m['db_name']};charset=utf8mb4",$m['db_user'],$m['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);tenantInstall($pool[$storeId]);return $pool[$storeId];}catch(Throwable $e){return null;}}
function tenantInstall($p){static $done=[];$key=spl_object_id($p);if(isset($done[$key]))return;$done[$key]=true;foreach([
"CREATE TABLE IF NOT EXISTS products (id VARCHAR(64) PRIMARY KEY,sku VARCHAR(120),title VARCHAR(255) NOT NULL,price DECIMAL(14,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,data LONGTEXT NOT NULL,updated_at DATETIME NOT NULL,INDEX(sku)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS orders (id VARCHAR(64) PRIMARY KEY,customer_user_id VARCHAR(64),status VARCHAR(60) NOT NULL,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,data LONGTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(status),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS coupons (id VARCHAR(64) PRIMARY KEY,code VARCHAR(80) NOT NULL,data LONGTEXT NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
] as $sql)$p->exec($sql);}
function hydrateStoreTenant($s,$storeId){if(!$storeId)return $s;$t=tenantDb($storeId);if(!$t)return $s;$s['products']=array_map(fn($x)=>json_decode($x['data'],true)?:[],$t->query('SELECT data FROM products ORDER BY updated_at DESC')->fetchAll());$s['orders']=array_map(fn($x)=>json_decode($x['data'],true)?:[],$t->query('SELECT data FROM orders ORDER BY created_at DESC')->fetchAll());$s['coupons']=array_map(fn($x)=>json_decode($x['data'],true)?:[],$t->query('SELECT data FROM coupons ORDER BY updated_at DESC')->fetchAll());return $s;}
function syncStore($s,$merchantId=null){
 if(empty($s['id'])||empty($s['slug'])||empty($s['name']))out(['status'=>'error','message'=>'بيانات المتجر غير مكتملة.'],422);
 $p=db();$now=date('Y-m-d H:i:s');$row=getStoreRow($s['id']);$owner=$merchantId??($row['merchant_user_id']??($s['merchantUserId']??null));
 $s['merchantUserId']=$owner;
 $tenant=tenantDb($s['id']);
 $central=$s;$central['products']=[];$central['orders']=[];$central['coupons']=[];
 $q=$p->prepare("INSERT INTO stores(id,slug,name,merchant_user_id,data,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE slug=VALUES(slug),name=VALUES(name),merchant_user_id=VALUES(merchant_user_id),data=VALUES(data),updated_at=VALUES(updated_at)");
 $created=$row['created_at']??$now;$q->execute([$s['id'],$s['slug'],$s['name'],$owner,json_encode($central,JSON_UNESCAPED_UNICODE),$created,$now]);
 if($tenant){
   $up=$tenant->prepare('INSERT INTO products(id,sku,title,price,stock,data,updated_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE sku=VALUES(sku),title=VALUES(title),price=VALUES(price),stock=VALUES(stock),data=VALUES(data),updated_at=VALUES(updated_at)');
   foreach(($s['products']??[]) as $x)$up->execute([$x['id'],$x['sku']??null,$x['title']??'',(float)($x['price']??0),(int)($x['stock']??0),json_encode($x,JSON_UNESCAPED_UNICODE),$now]);
   $up=$tenant->prepare('INSERT INTO coupons(id,code,data,updated_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE code=VALUES(code),data=VALUES(data),updated_at=VALUES(updated_at)');
   foreach(($s['coupons']??[]) as $x)$up->execute([$x['id'],$x['code']??'',json_encode($x,JSON_UNESCAPED_UNICODE),$now]);
   if(isset($s['orders'])){ $up=$tenant->prepare('INSERT INTO orders(id,customer_user_id,status,total_amount,data,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE customer_user_id=VALUES(customer_user_id),status=VALUES(status),total_amount=VALUES(total_amount),data=VALUES(data),updated_at=VALUES(updated_at)'); foreach(($s['orders']??[]) as $x)$up->execute([$x['id'],null,$x['status']??'جديد',(float)($x['totalAmount']??0),json_encode($x,JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s'),$now]); }
 } else {
   $up=$p->prepare('INSERT INTO products(id,store_id,sku,title,price,stock,data,updated_at) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE sku=VALUES(sku),title=VALUES(title),price=VALUES(price),stock=VALUES(stock),data=VALUES(data),updated_at=VALUES(updated_at)');foreach(($s['products']??[]) as $x)$up->execute([$x['id'],$s['id'],$x['sku']??null,$x['title']??'',(float)($x['price']??0),(int)($x['stock']??0),json_encode($x,JSON_UNESCAPED_UNICODE),$now]);
   $up=$p->prepare('INSERT INTO coupons(id,store_id,code,data,updated_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE code=VALUES(code),data=VALUES(data),updated_at=VALUES(updated_at)');foreach(($s['coupons']??[]) as $x)$up->execute([$x['id'],$s['id'],$x['code']??'',json_encode($x,JSON_UNESCAPED_UNICODE),$now]);
 }
 if(isset($s['subscription']))$p->prepare("INSERT INTO subscriptions(id,store_id,status,data,updated_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),data=VALUES(data),updated_at=VALUES(updated_at)")->execute(['sub-'.$s['id'],$s['id'],$s['subscription']['status']??'active_trial',json_encode($s['subscription'],JSON_UNESCAPED_UNICODE),$now]);
 return $s;
}
function publicStore($s){if(!is_array($s))return $s;$s['orders']=[];if(isset($s['stats']))$s['stats']['totalSales']=0;$s['email']='';$s['phone']='';if(isset($s['settings']['shippingApiSettings']['apiKey']))$s['settings']['shippingApiSettings']['apiKey']='';
 return $s;}
function allStores($public=true){$r=db()->query('SELECT data FROM stores ORDER BY created_at DESC')->fetchAll();return array_map(fn($x)=>$public?publicStore(decodeStore($x)):decodeStore($x),$r);}
function admin(){return requireUser(['admin']);}
function merchantStore($id){$u=requireUser(['merchant']);if(!owned($id,$u['id']))out(['status'=>'error','message'=>'لا تملك هذا المتجر.'],403);$r=getStoreRow($id);if(!$r)out(['status'=>'error','message'=>'المتجر غير موجود.'],404);return decodeStore($r);}
install();$action=$_GET['action']??'status';
if($action==='tenant_status'){admin();$d=body();$m=tenantMeta($d['storeId']??'');out(['status'=>'success','enabled'=>tenantConfig()['enabled'],'configured'=>(bool)$m,'database'=>$m['db_name']??null,'connected'=>(bool)tenantDb($d['storeId']??'')]);}
if($action==='provision_tenant'){admin();$d=body();$storeId=$d['storeId']??'';$r=getStoreRow($storeId);if(!$r)out(['status'=>'error','message'=>'المتجر غير موجود.'],404);$c=tenantConfig();if(!$c['enabled'])out(['status'=>'error','message'=>'فعّل tenant_databases_enabled في public/config.php.'],400);$name=preg_replace('/[^a-zA-Z0-9_]/','_',($c['prefix'].$storeId));$host=$c['host'];$user=$c['user'];$pass=$c['pass'];try{$adminP=new PDO("mysql:host={$host};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$adminP->exec('CREATE DATABASE IF NOT EXISTS `'.$name.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$p=db();$p->prepare('INSERT INTO tenant_databases(store_id,db_name,db_host,db_user,db_pass,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE db_name=VALUES(db_name),db_host=VALUES(db_host),db_user=VALUES(db_user),db_pass=VALUES(db_pass),status=VALUES(status),updated_at=VALUES(updated_at)')->execute([$storeId,$name,$host,$user,$pass,'active',date('Y-m-d H:i:s'),date('Y-m-d H:i:s')]);$s=json_decode($r['data']??'{}',true);if(!is_array($s))$s=[];$s=syncStore($s,$r['merchant_user_id']??null);out(['status'=>'success','message'=>'تم تجهيز قاعدة بيانات البائع.','database'=>$name]);}catch(Throwable $e){out(['status'=>'error','message'=>'تعذر إنشاء قاعدة بيانات البائع. على InfinityFree قد تحتاج إنشاء قاعدة البيانات من لوحة الاستضافة ثم وضع بياناتها في tenant_databases.'],500);}}
if($action==='status'){out(['status'=>'success','server'=>'InfinityFree PHP/MySQL','database'=>'connected','mysql_version'=>db()->query('SELECT VERSION() v')->fetch()['v'],'timestamp'=>date('c')]);}
