if($action==='register'){ $d=body();$role=in_array(($d['role']??'buyer'),['buyer','merchant'],true)?$d['role']:'buyer';if(empty($d['phone'])||empty($d['name'])||empty($d['password']))out(['status'=>'error','message'=>'الاسم والهاتف وكلمة المرور مطلوبة.'],422);$p=db();$q=$p->prepare('SELECT id FROM users WHERE phone=? OR (email IS NOT NULL AND email=?) LIMIT 1');$q->execute([$d['phone'],$d['email']??'']);if($q->fetch())out(['status'=>'error','message'=>'رقم الهاتف أو البريد الإلكتروني مستخدم بالفعل.'],409);$id='usr-'.bin2hex(random_bytes(8));$p->prepare('INSERT INTO users(id,name,phone,email,company_name,role,status,password_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,$d['name'],$d['phone'],$d['email']??null,$d['companyName']??null,$role,'active',password_hash($d['password'],PASSWORD_DEFAULT),date('Y-m-d H:i:s')]);$_SESSION['user']=['id'=>$id,'name'=>$d['name'],'phone'=>$d['phone'],'company_name'=>$d['companyName']??null,'role'=>$role,'status'=>'active'];out(['status'=>'success','user'=>publicUser($_SESSION['user'])]); }
if($action==='login'){ $d=body();$p=db();$q=$p->prepare('SELECT * FROM users WHERE phone=? OR email=? LIMIT 1');$q->execute([$d['login']??'',$d['login']??'']);$u=$q->fetch();if(!$u||empty($u['password_hash'])||!password_verify($d['password']??'',$u['password_hash']))out(['status'=>'error','message'=>'بيانات الدخول غير صحيحة.'],401);if(($u['status']??'active')==='suspended')out(['status'=>'error','message'=>'حساب البائع موقوف من الإدارة.'],403);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'phone'=>$u['phone'],'company_name'=>$u['company_name'],'role'=>$u['role'],'status'=>$u['status']??'active'];out(['status'=>'success','user'=>publicUser($_SESSION['user'])]); }
if($action==='admin_login'){ $d=body();$p=db();$login=trim((string)($d['username']??''));$q=$p->prepare("SELECT * FROM users WHERE role='admin' AND (email=? OR name=? OR phone=?) LIMIT 1");$q->execute([$login,$login,$login]);$u=$q->fetch();if(!$u||($u['status']??'active')!=='active'||empty($u['password_hash'])||!password_verify((string)($d['password']??''),$u['password_hash']))out(['status'=>'error','message'=>'بيانات المدير غير صحيحة.'],401);session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'phone'=>$u['phone'],'company_name'=>$u['company_name'],'role'=>'admin','status'=>'active'];out(['status'=>'success','user'=>publicUser($_SESSION['user'])]); }
if($action==='stores'){out(['status'=>'success','stores'=>allStores(true)]);}
if($action==='my_stores'){ $u=requireUser(['merchant','admin']);if($u['role']==='admin')out(['status'=>'success','stores'=>allStores(false)]);$q=db()->prepare('SELECT data FROM stores WHERE merchant_user_id=? ORDER BY created_at DESC');$q->execute([$u['id']]);out(['status'=>'success','stores'=>array_map(fn($x)=>decodeStore($x),$q->fetchAll())]); }
if($action==='create_store'){ $u=requireUser(['merchant']);$s=body();if(empty($s['id'])||empty($s['slug'])||empty($s['name']))out(['status'=>'error','message'=>'بيانات المتجر ناقصة.'],422);$q=db()->prepare('SELECT id FROM stores WHERE slug=? LIMIT 1');$q->execute([$s['slug']]);if($q->fetch())out(['status'=>'error','message'=>'رابط المتجر مستخدم بالفعل.'],409);$qOwner=db()->prepare('SELECT id FROM stores WHERE merchant_user_id=? LIMIT 1');$qOwner->execute([$u['id']]);if($qOwner->fetch())out(['status'=>'error','message'=>'لديك متجر بالفعل. يُسمح بمتجر واحد فقط لكل بائع.'],400);$s['merchantUserId']=$u['id'];out(['status'=>'success','store'=>syncStore($s,$u['id'])]); }
